<?php

declare(strict_types=1);

namespace Src\Shared\Domain\Contracts;

use Src\Shared\Domain\Exceptions\FileOutsideBarbershopException;

interface BarbershopFileStorage
{
    /**
     * Keep a copy of a file in the folder of the current barbershop, under a name generated by the server, and answer its path.
     *
     * @throws FileOutsideBarbershopException
     */
    public function store(string $directory, string $sourcePath, string $extension): string;

    /**
     * Delete a stored file; a missing file is ignored.
     *
     * @throws FileOutsideBarbershopException
     */
    public function delete(string $path): void;

    /**
     * Public address of a stored file.
     *
     * @throws FileOutsideBarbershopException
     */
    public function url(string $path): string;
}
